#!/usr/bin/env bash
#
# nexum-bridge-debug.sh
# =============================================================================
# TEMPORARY debug patch: surface the REAL bridge failure reason on-screen.
#
# Patches nexum-web/hooks/useBridge.ts so that when a bridge fails with an
# unexpected error (not re-auth / wrong-chain / network), the on-screen error
# shows: [which step failed] + the deepest nested detail from the Circle /
# on-chain error + a trimmed raw dump. This tells us whether the failure is the
# approve, the transferFrom (allowance), a vault require, or a CCTP revert.
#
# Known cases (re-auth, wrong chain, network) are left with their clean
# messages - only genuinely unexpected errors get the verbose dump.
#
# REMOVE after diagnosing: bash nexum-bridge-debug.sh --revert
#
# VERIFY AFTER: cd nexum-web && rm -rf .next && npx tsc --noEmit && npm run build
# =============================================================================
set -euo pipefail

find_root() {
  local d="$PWD"
  while [ "$d" != "/" ]; do
    if [ -d "$d/nexum-web/hooks" ]; then echo "$d"; return 0; fi
    d="$(dirname "$d")"
  done
  if [ -d "$HOME/AfriFX/Nexum-main/nexum-web/hooks" ]; then echo "$HOME/AfriFX/Nexum-main"; return 0; fi
  if [ -d "$HOME/AfriFX/nexum-web/hooks" ]; then echo "$HOME/AfriFX"; return 0; fi
  return 1
}
ROOT="$(find_root)" || { echo "ERROR: repo root not found (needs nexum-web/hooks)."; exit 1; }
echo "Repo root: $ROOT"

STAMP="$(date +%Y%m%d-%H%M%S)"
BACKUP_DIR="$ROOT/.nexum-bridge-debug-backups"
UB_PATH="$ROOT/nexum-web/hooks/useBridge.ts"
UB_SHA="4222b95c77c45569bbd356d5e1dc8c48ef31bc38d052523f27150ce947df429f"; UB_B64=""

revert() {
  echo "== REVERT =="
  local pristine
  pristine="$(ls -1tr "$BACKUP_DIR"/useBridge.ts.* 2>/dev/null | head -n1 || true)"
  if [ -n "${pristine:-}" ] && [ -f "$pristine" ]; then
    cp -f "$pristine" "$UB_PATH" && echo "restored useBridge.ts from backup"
  else
    echo "no backup found (leaving current file)"
  fi
  rm -f "$BACKUP_DIR"/useBridge.ts.*
  rmdir "$BACKUP_DIR" 2>/dev/null || true
  echo "revert complete."
}
if [ "${1:-}" = "--revert" ]; then revert; exit 0; fi

mkdir -p "$BACKUP_DIR"
tmp="$(mktemp)"
printf '%s' "$UB_B64" | base64 -d > "$tmp" || { echo "ERROR: decode failed"; rm -f "$tmp"; exit 1; }
got="$(sha256sum "$tmp" | cut -d' ' -f1)"
if [ "$got" != "$UB_SHA" ]; then echo "ERROR: checksum mismatch"; echo "  expected $UB_SHA"; echo "  got      $got"; rm -f "$tmp"; exit 1; fi
echo "  verified useBridge.ts (sha256 ok)"
[ -f "$UB_PATH" ] && [ ! -f "$BACKUP_DIR/useBridge.ts.$STAMP" ] && cp -f "$UB_PATH" "$BACKUP_DIR/useBridge.ts.$STAMP" && echo "  backed up existing useBridge.ts"
mv -f "$tmp" "$UB_PATH"
echo "  wrote $UB_PATH"
echo
echo "== DONE =="
echo "Deploy (git push) or run locally, trigger a bridge, and read the red error"
echo "on the bridge page. Paste it to me. Then revert: bash $(basename "$0") --revert"
